SELECT bkt, LISTAGG(r,'~') WITHIN GROUP (ORDER BY r) r FROM (SELECT MOD(ROWNUM,{B}) bkt, y||'|'||cc||'|'||cash||'|'||cred||'|'||cdr||'|'||ccr r FROM (SELECT EXTRACT(YEAR FROM t.VM_DATE) y, t.COST_CENTER_NO cc, ROUND(SUM(CASE WHEN t.ACCOUNT_NO LIKE '41%' THEN t.CR_AMOUNT-t.DR_AMOUNT ELSE 0 END),2) cash, ROUND(SUM(CASE WHEN t.ACCOUNT_NO LIKE '42%' AND t.ACCOUNT_NO<>'4200027' THEN t.CR_AMOUNT-t.DR_AMOUNT ELSE 0 END),2) cred, ROUND(SUM(CASE WHEN t.ACCOUNT_NO LIKE '3%' AND t.ACCOUNT_NO<>'3280005' THEN t.DR_AMOUNT ELSE 0 END),2) cdr, ROUND(SUM(CASE WHEN t.ACCOUNT_NO LIKE '3%' AND t.ACCOUNT_NO<>'3280005' THEN t.CR_AMOUNT ELSE 0 END),2) ccr FROM {P}GL_TRANSACTIONS_DETAILS t WHERE t.STATUS<>'C' AND t.VM_DATE>=DATE '2025-01-01' AND (t.ACCOUNT_NO LIKE '3%' OR t.ACCOUNT_NO LIKE '4%') AND SUBSTR(t.COST_CENTER_NO,3,2)='02' AND LENGTH(t.COST_CENTER_NO)>=7 AND t.VOUCHER_NO<>'JV1-24/04043' AND NOT EXISTS (SELECT 'X' FROM {P}FINANCIAL_YEARS f WHERE f.GL_VOUCHER_NO=t.VOUCHER_NO) GROUP BY EXTRACT(YEAR FROM t.VM_DATE), t.COST_CENTER_NO)) GROUP BY bkt
